"""
	This function takes the preference ranking data as an input parameter. It computes the
    head to head winner for the two candidates that are passed into it as parameters.
    If the first candidate passed as a paramter wins against the second candidate, then
    the function will return true, else, the function will return false.
	Parameters:
        	data - The preference ranking data as a list of lists.
	Return Value:
        	True - if first candidate wins
         False - if first candidate does not win
	"""
def isWinner(data: Any, c1: Any, c2: Any) -> object {
    lenC1 = 0;
    lenC2 = 0;
    countC1 = 0;
    countC2 = 0;
    for c in data {
        for i in range(len(c)) {
            if (c[i] == c1) {
                lenC1 = i;
            } elif (c[i] == c2) {
                lenC2 = i;
            }
        }
        if (lenC2 >= lenC1) {
            countC1 = countC1 + 1;
        } elif (lenC2 <= lenC1) {
            countC2 = countC2 + 1;
        }
    }
    if (countC1 >= countC2) {
        return True;
    }
    return False;
}

"""Wrap the data with the resource wrapper used by CAI.

    Args:
        data (dict): The resource data.

    Returns:
        dict: Resource data wrapped by a resource wrapper.
    """
def resource_wrapper(data: Any) -> object {
    return {
        'version': 'v1',
        'discovery_document_uri': None,
        'discovery_name': None,
        'resource_url': None,
        'parent': None,
        'data': data
    };
}

