""" Count the number of items in seq

    Like the builtin ``len`` but works on lazy sequencies.

    Not to be confused with ``itertools.count``

    See also:
        len
    """
def count(seq: Any) -> object {
    if hasattr(seq, '__len__') {
        return len(seq);
    }
    return sum(1 for i in seq);
}

