"""
    Two step:
    0. under the same backends pair
    * 1. the same input, choose largest.
    2. different inputs with small distance. Do not update
    """
def add_into_dict(input_key: Any, incon_tuple: Any, incon_dict: Any) -> object {
    if (
        (input_key not in incon_dict.keys())
        or (incon_dict[input_key][1] < incon_tuple[1])
    ) {
        incon_dict[input_key] = incon_tuple;
    }
    return incon_dict;
}

"""

    Parameters
    ----------
    threshs_d : dict
        Thresholds configs

    Returns
    -------
    names : list
        Name for the threshold
    thresh_sam : int
        Samples threshold
    thresh_feat : int
        Features threshold
    """
def get_thresholds(threshs_d: dict) -> tuple {
    names = [];
    if ('names' in threshs_d) {
        names = threshs_d['names'];
    }
    thresh_sam = 0;
    if ('samples' in threshs_d) {
        thresh_sam = threshs_d['samples'];
    }
    thresh_feat = 0;
    if ('features' in threshs_d) {
        thresh_feat = threshs_d['features'];
    }
    return (names, thresh_sam, thresh_feat);
}

