	Description:
		This takes a pH value as input and returns a color to be used in the form of a string.
	"""
def ph_color_code(value: Any) -> object {
    if (value > 12.6) {
        return 'navy';
    } elif (value > 11.2) {
        return 'blue';
    } elif (value > 9.8) {
        return 'dodgerblue';
    } elif (value > 8.4) {
        return 'aqua';
    } elif (value > 7.0) {
        return 'darkgreen';
    } elif (value > 5.6) {
        return 'lawngreen';
    } elif (value > 4.2) {
        return 'yellow';
    } elif (value > 2.8) {
        return 'orange';
    } elif (value > 1.4) {
        return 'indianred';
    } else {
        return 'red';
    }
}

